import { useState, useEffect } from 'react';

const GROQ_URL   = 'https://api.groq.com/openai/v1/chat/completions';
const GROQ_KEY   = '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';
const GROQ_MODEL = 'llama-3.3-70b-versatile';

async function groqChat(sys, usr, max = 1000, temp = 0.7) {
  const r = await fetch(GROQ_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${GROQ_KEY}` },
    body: JSON.stringify({ model: GROQ_MODEL, max_tokens: max, temperature: temp,
      messages: [{ role: 'system', content: sys }, { role: 'user', content: usr }] }),
  });
  const d = await r.json();
  if (!r.ok) throw new Error(d?.error?.message || `AI error ${r.status}`);
  return d.choices?.[0]?.message?.content?.trim() || '';
}

const API      = 'http://localhost:5000/api';
const getToken = () => localStorage.getItem('examai_token');

const gc  = pct => pct>=90?'#16a34a':pct>=75?'#2563eb':pct>=60?'#d97706':pct>=50?'#9333ea':'#dc2626';
const gcBg= pct => pct>=90?'#dcfce7':pct>=75?'#dbeafe':pct>=60?'#fef3c7':pct>=50?'#f3e8ff':'#fee2e2';
const grade=pct => pct>=90?'A+':pct>=80?'A':pct>=70?'B':pct>=60?'C':pct>=50?'D':'F';
const dCol= d   => d==='Easy'?'#16a34a':d==='Hard'?'#dc2626':'#d97706';
const dBg = d   => d==='Easy'?'#dcfce7':d==='Hard'?'#fee2e2':'#fef3c7';

const ResultView = ({ submissionId, store, onBack }) => {
  const [loading,   setLoading]   = useState(true);
  const [result,    setResult]    = useState(null);
  const [sub,       setSub]       = useState(null);
  const [exam,      setExam]      = useState(null);
  const [questions, setQuestions] = useState([]);
  const [answers,   setAnswers]   = useState([]);
  const [tab,       setTab]       = useState('review'); // review | analytics

  // Analytics state
  const [analysis,   setAnalysis]   = useState(null);
  const [analyzing,  setAnalyzing]  = useState(false);
  const [analysisErr,setAnalysisErr]= useState('');

  useEffect(() => { loadAll(); }, [submissionId]);

  const apiFetch = async (path) => {
    const res = await fetch(`${API}${path}`, { headers:{ Authorization:`Bearer ${getToken()}` } });
    return res.json();
  };

  const loadAll = async () => {
    try {
      setLoading(true);
      const resultData = await apiFetch(`/submissions/result/${submissionId}`);
      setResult(resultData);
      const subsData   = await apiFetch(`/submissions/student/${store.getStudentSid()}`);
      const subData    = subsData.find(s => s.submission_id === submissionId);
      setSub(subData);
      if (subData) {
        const [examsData, qData, ansData] = await Promise.all([
          apiFetch('/exams'),
          apiFetch(`/questions/${subData.exam_id}`),
          apiFetch(`/submissions/answers/${submissionId}`),
        ]);
        setExam(examsData.find(e => e.exam_id === subData.exam_id));
        setQuestions(qData);
        setAnswers(Array.isArray(ansData) ? ansData : []);
      }
    } catch(e) { console.error(e); }
    finally { setLoading(false); }
  };

  const generateAnalysis = async () => {
    if (!questions.length || !exam) return;
    setAnalyzing(true); setAnalysisErr('');
    const answerMap = {};
    answers.forEach(a => { answerMap[a.question_id] = a; });
    const breakdown = questions.map((q,i) => {
      const ans = answerMap[q.question_id];
      const studentAns = ans?.answer_text || '(no answer)';
      const isAuto = q.question_type==='MCQ'||q.question_type==='TRUE_FALSE';
      const correct = isAuto ? studentAns.trim().toLowerCase()===(q.correct_answer||'').trim().toLowerCase() : null;
      return `Q${i+1} [${q.difficulty}|${q.question_type}]: ${q.question_text} | Student: ${studentAns} | ${correct===null?'Open-ended':correct?'Correct':'Wrong'} | Marks: ${q.marks}`;
    }).join('\n');
    const totalScore = Number(result?.total_score)||0;
    const pct = Math.round(totalScore/Number(exam.total_marks)*100);
    try {
      const sys = 'You are an expert academic tutor. Return ONLY valid JSON, no markdown.';
      const usr = `Analyze this student exam performance and provide detailed feedback.

Exam: ${exam.title}
Score: ${totalScore}/${exam.total_marks} (${pct}%)

Question breakdown:
${breakdown}

Return JSON:
{
  "strengths": [{"topic":"<topic name>","detail":"<what they did well>"},{"topic":"...","detail":"..."}],
  "weaknesses": [{"topic":"<topic name>","detail":"<what they got wrong and why>"},{"topic":"...","detail":"..."}],
  "improvements": ["<specific actionable tip 1>","<specific actionable tip 2>","<specific actionable tip 3>","<specific actionable tip 4>"],
  "level": "<Beginner|Developing|Proficient|Advanced|Expert>",
  "readiness": "<Not Ready|Needs Work|Almost Ready|Ready>",
  "summary": "<2-3 sentence overall assessment>",
  "focus_topics": ["<topic to study most urgently>","<second priority>"]
}`;
      const data = await groqChat(sys, usr, 900);
      setAnalysis(data);
    } catch(e) {
      setAnalysisErr('Analysis failed. Please try again.');
    }
    setAnalyzing(false);
  };

  if (loading) return (
    <div style={{ display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', padding:80, gap:16 }}>
      <div style={{ width:40, height:40, borderRadius:'50%', border:'3px solid #e8e8f0', borderTop:'3px solid #7c3aed', animation:'spin .7s linear infinite' }}/>
      <div style={{ color:'#6b7280', fontSize:14 }}>Loading results...</div>
    </div>
  );

  if (!result || !exam) return (
    <div>
      <button onClick={onBack} style={{ display:'inline-flex', alignItems:'center', gap:6, padding:'6px 14px', background:'#fff', border:'1px solid #e5e7eb', borderRadius:8, fontSize:13, fontWeight:600, color:'#374151', cursor:'pointer', marginBottom:20 }}>← Back</button>
      <div style={{ textAlign:'center', padding:48 }}><div style={{ fontSize:40, marginBottom:12, opacity:.3 }}>❌</div><div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:16, color:'#374151' }}>Result not found</div></div>
    </div>
  );

  const isCheated    = result.cheating_detected;
  const totalScore   = isCheated ? 0 : (Number(result.total_score)||0);
  const pct          = isCheated ? 0 : exam ? Math.round((totalScore/exam.total_marks)*100) : 0;
  const g            = isCheated ? 'F' : grade(pct);
  const color        = isCheated ? '#dc2626' : gc(pct);
  const bgColor      = isCheated ? '#fee2e2' : gcBg(pct);
  const duration     = sub?.submit_time && sub?.start_time
    ? Math.round((new Date(sub.submit_time)-new Date(sub.start_time))/60000) : 0;

  const answerMap = {};
  answers.forEach(a => { answerMap[a.question_id] = a; });

  const correctCount = questions.filter(q => {
    const ans = answerMap[q.question_id];
    if (!ans || q.question_type==='SHORT_ANSWER' || q.question_type==='DESCRIPTIVE') return false;
    return (ans.answer_text||'').trim().toLowerCase()===(q.correct_answer||'').trim().toLowerCase();
  }).length;

  const getSuggestion = () => {
    if (isCheated) return { bg:'#fef2f2', border:'#fecaca', icon:'⚠', title:'Integrity Violation', text:'This submission was flagged for a tab switch during the exam. Result recorded as 0.', color:'#dc2626' };
    if (pct>=90) return { bg:'#f0fdf4', border:'#bbf7d0', icon:'🏆', title:'Outstanding!',      text:`${pct}% — excellent work. Your understanding is exceptional.`, color:'#16a34a' };
    if (pct>=75) return { bg:'#eff6ff', border:'#bfdbfe', icon:'🎯', title:'Great Job!',        text:`${pct}% — well above average. Review the few questions you missed.`, color:'#2563eb' };
    if (pct>=50) return { bg:'#fefce8', border:'#fef08a', icon:'📘', title:'Good Effort',       text:`${pct}% — passing. Focus on the areas you got wrong.`, color:'#ca8a04' };
    return               { bg:'#fef2f2', border:'#fecaca', icon:'💪', title:'Keep Going',       text:`${pct}% — review the material and try again. Every attempt improves your understanding.`, color:'#dc2626' };
  };
  const sugg = getSuggestion();

  return (
    <div style={{ maxWidth:860, margin:'0 auto' }}>
      {/* Back */}
      <button onClick={onBack} style={{ display:'inline-flex', alignItems:'center', gap:6, padding:'6px 14px', background:'#fff', border:'1px solid #e5e7eb', borderRadius:8, fontSize:13, fontWeight:600, color:'#374151', cursor:'pointer', marginBottom:20 }}>
        ← Back
      </button>

      {/* Cheating banner */}
      {isCheated && (
        <div style={{ background:'#fef2f2', border:'2px solid #fca5a5', borderRadius:14, padding:'18px 22px', marginBottom:18, display:'flex', gap:14, alignItems:'center' }}>
          <div style={{ width:48, height:48, borderRadius:12, background:'#fee2e2', display:'flex', alignItems:'center', justifyContent:'center', fontSize:24, flexShrink:0 }}>⚠</div>
          <div>
            <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:800, fontSize:17, color:'#dc2626', marginBottom:4 }}>Integrity Violation Detected</div>
            <div style={{ fontSize:13, color:'#7f1d1d', lineHeight:1.65 }}>A tab switch was detected during this exam. The result has been recorded as <strong>0</strong>.</div>
          </div>
        </div>
      )}

      {/* Score hero */}
      <div style={{ background:'#fff', border:'1px solid #e8e8f0', borderRadius:16, padding:'30px 26px', marginBottom:18, textAlign:'center', boxShadow:'0 1px 4px rgba(0,0,0,.06)', position:'relative', overflow:'hidden' }}>
        <div style={{ position:'absolute', inset:0, background:`radial-gradient(ellipse at 50% 0%, ${color}08, transparent 60%)`, pointerEvents:'none' }}/>
        <div style={{ position:'absolute', top:0, left:0, right:0, height:4, background:`linear-gradient(90deg,transparent,${color},transparent)` }}/>

        {/* Ring */}
        <div style={{ position:'relative', width:120, height:120, margin:'0 auto 16px' }}>
          <svg width="120" height="120" style={{ transform:'rotate(-90deg)', position:'absolute', top:0, left:0 }}>
            <circle cx="60" cy="60" r="52" fill="none" stroke="#f3f4f6" strokeWidth="8"/>
            <circle cx="60" cy="60" r="52" fill="none" stroke={color} strokeWidth="8"
              strokeDasharray={`${pct*3.267} 326.7`} strokeLinecap="round"/>
          </svg>
          <div style={{ position:'absolute', inset:0, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center' }}>
            <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:900, fontSize:28, color, lineHeight:1 }}>{g}</div>
            <div style={{ fontSize:11, color:'#9ca3af', fontFamily:'JetBrains Mono,monospace', marginTop:2 }}>{pct}%</div>
          </div>
        </div>

        <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:900, fontSize:42, color, lineHeight:1, marginBottom:5 }}>
          {isCheated ? '0' : totalScore.toFixed(1)}
          <span style={{ fontSize:20, color:'#9ca3af', fontWeight:400 }}>/{exam.total_marks}</span>
        </div>
        <div style={{ fontSize:13, color:'#6b7280', marginBottom:18, fontFamily:'JetBrains Mono,monospace' }}>{pct}% · {exam.title}</div>

        <div style={{ height:6, background:'#f3f4f6', borderRadius:3, overflow:'hidden', maxWidth:400, margin:'0 auto 18px' }}>
          <div style={{ height:'100%', width:`${pct}%`, background:`linear-gradient(90deg,${color}88,${color})`, borderRadius:3 }}/>
        </div>

        <div style={{ display:'flex', gap:0, justifyContent:'center' }}>
          {[
            {label:'TIME TAKEN', value:`${duration} min`},
            {label:'CORRECT',    value:isCheated?'0':String(correctCount)},
            {label:'TOTAL Qs',   value:String(questions.length)},
          ].map((s,i) => (
            <div key={i} style={{ display:'flex', alignItems:'center' }}>
              {i>0&&<div style={{ width:1, height:30, background:'#e8e8f0', margin:'0 18px' }}/>}
              <div style={{ textAlign:'center' }}>
                <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:800, fontSize:20, color:'#0f0f1a', lineHeight:1 }}>{s.value}</div>
                <div style={{ fontSize:9, color:'#9ca3af', fontFamily:'JetBrains Mono,monospace', letterSpacing:1.5, marginTop:3 }}>{s.label}</div>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Suggestion */}
      <div style={{ background:sugg.bg, border:`1px solid ${sugg.border}`, borderRadius:12, padding:'14px 18px', marginBottom:18, display:'flex', gap:12, alignItems:'flex-start' }}>
        <span style={{ fontSize:22, flexShrink:0 }}>{sugg.icon}</span>
        <div>
          <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:14, color:sugg.color, marginBottom:4 }}>{sugg.title}</div>
          <div style={{ fontSize:13, color:'#374151', lineHeight:1.65 }}>{sugg.text}</div>
        </div>
      </div>

      {/* Tabs — only show if not cheated */}
      {!isCheated && (
        <>
          <div style={{ display:'flex', gap:2, marginBottom:18, background:'#f3f4f6', padding:3, borderRadius:10, border:'1px solid #e5e7eb' }}>
            {[
              {k:'review',    l:'📋 Detailed Review'},
              {k:'analytics', l:'📊 Analytics'},
            ].map(t => (
              <button key={t.k} onClick={() => { setTab(t.k); if (t.k==='analytics'&&!analysis&&!analyzing) generateAnalysis(); }}
                style={{ flex:1, padding:'9px 16px', borderRadius:8, border:'none', cursor:'pointer', fontSize:13, fontWeight:600, transition:'all .15s',
                  background:tab===t.k?'#fff':'transparent',
                  color:tab===t.k?'#0f0f1a':'#6b7280',
                  boxShadow:tab===t.k?'0 1px 4px rgba(0,0,0,.08)':'' }}>
                {t.l}
              </button>
            ))}
          </div>

          {/* ── REVIEW TAB ── */}
          {tab==='review' && (
            <div style={{ background:'#fff', border:'1px solid #e8e8f0', borderRadius:14, overflow:'hidden', boxShadow:'0 1px 3px rgba(0,0,0,.06)' }}>
              <div style={{ padding:'14px 20px', borderBottom:'1px solid #f3f4f6' }}>
                <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:15, color:'#0f0f1a' }}>Detailed Review</div>
              </div>

              {questions.length===0 ? (
                <div style={{ textAlign:'center', padding:40 }}>
                  <div style={{ fontSize:28, marginBottom:10, opacity:.25 }}>📋</div>
                  <div style={{ fontSize:14, color:'#9ca3af' }}>No questions found for this exam.</div>
                </div>
              ) : questions.map((q,i) => {
                const ans        = answerMap[q.question_id];
                const studentAns = ans?.answer_text || '';
                const isAuto     = q.question_type==='MCQ'||q.question_type==='TRUE_FALSE';
                const isOpen     = !isAuto;
                const isCorrect  = isAuto && studentAns.trim().toLowerCase()===(q.correct_answer||'').trim().toLowerCase();
                const notAns     = !studentAns;
                const earnedMks  = isCorrect ? q.marks : isOpen ? '~' : 0;
                const borderCol  = isCorrect?'#16a34a':isOpen?'#d97706':notAns?'#e5e7eb':'#dc2626';
                const tagCol     = isCorrect?'#16a34a':isOpen?'#d97706':notAns?'#9ca3af':'#dc2626';
                const tagBg      = isCorrect?'#dcfce7':isOpen?'#fef3c7':notAns?'#f3f4f6':'#fee2e2';
                const tagLabel   = isCorrect?'Correct':isOpen?'Open-ended':notAns?'No Answer':'Incorrect';
                return (
                  <div key={q.question_id} style={{ padding:'16px 20px', borderBottom:'1px solid #f3f4f6', borderLeft:`3px solid ${borderCol}` }}>
                    <div style={{ display:'flex', justifyContent:'space-between', alignItems:'flex-start', gap:12, marginBottom:10 }}>
                      <div style={{ flex:1 }}>
                        <div style={{ display:'flex', gap:6, marginBottom:6, flexWrap:'wrap', alignItems:'center' }}>
                          <span style={{ fontSize:10, color:'#9ca3af', fontFamily:'JetBrains Mono,monospace', background:'#f3f4f6', padding:'2px 7px', borderRadius:4 }}>Q{i+1}</span>
                          {q.difficulty&&<span style={{ padding:'2px 8px', borderRadius:20, background:dBg(q.difficulty), color:dCol(q.difficulty), fontSize:10, fontWeight:700, fontFamily:'JetBrains Mono,monospace' }}>{q.difficulty}</span>}
                          <span style={{ padding:'2px 8px', borderRadius:20, background:tagBg, color:tagCol, fontSize:10, fontWeight:700, fontFamily:'JetBrains Mono,monospace' }}>{tagLabel}</span>
                        </div>
                        <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:600, fontSize:14, color:'#0f0f1a', lineHeight:1.55 }}>{q.question_text}</div>
                      </div>
                      <div style={{ flexShrink:0, background:isCorrect?'#dcfce7':isOpen?'#fef3c7':'#fee2e2', border:`1px solid ${borderCol}22`, borderRadius:8, padding:'5px 11px', textAlign:'center' }}>
                        <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:800, fontSize:15, color:borderCol }}>{earnedMks}</div>
                        <div style={{ fontSize:9, color:'#9ca3af', fontFamily:'JetBrains Mono,monospace' }}>/{q.marks}</div>
                      </div>
                    </div>

                    {/* MCQ options */}
                    {q.question_type==='MCQ'&&q.options?.length>0&&(
                      <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:5, marginBottom:10 }}>
                        {q.options.map((opt,oi)=>{
                          const letter=['A','B','C','D'][oi];
                          const isRight=q.correct_answer===letter, isMine=studentAns===letter;
                          return(<div key={oi} style={{ padding:'6px 10px', borderRadius:7, fontSize:12, display:'flex', alignItems:'center', gap:7, border:`1px solid ${isRight?'#bbf7d0':isMine&&!isRight?'#fecaca':'#e8e8f0'}`, background:isRight?'#f0fdf4':isMine&&!isRight?'#fef2f2':'#f8f8fc', color:isRight?'#16a34a':isMine&&!isRight?'#dc2626':'#374151' }}>
                            <span style={{ fontFamily:'JetBrains Mono,monospace', fontWeight:700, fontSize:10, width:16, flexShrink:0 }}>{letter}</span>
                            <span style={{ flex:1 }}>{opt.text}</span>
                            {isRight&&<span>✅</span>}{isMine&&!isRight&&<span>❌</span>}
                          </div>);
                        })}
                      </div>
                    )}

                    {/* Answer panels */}
                    <div style={{ display:'grid', gridTemplateColumns:isAuto&&q.correct_answer?'1fr 1fr':'1fr', gap:8, marginBottom:q.explanation?10:0 }}>
                      <div style={{ padding:'8px 12px', borderRadius:8, background:'#f8f8fc', border:'1px solid #e8e8f0' }}>
                        <div style={{ fontSize:9, fontWeight:700, color:'#9ca3af', fontFamily:'JetBrains Mono,monospace', marginBottom:4, letterSpacing:1 }}>YOUR ANSWER</div>
                        <div style={{ fontSize:13, color:isCorrect?'#16a34a':notAns?'#9ca3af':isOpen?'#374151':'#dc2626', fontStyle:notAns?'italic':'normal', fontWeight:isCorrect?700:500 }}>
                          {studentAns||'(not answered)'}
                        </div>
                      </div>
                      {isAuto&&q.correct_answer&&(
                        <div style={{ padding:'8px 12px', borderRadius:8, background:'#f0fdf4', border:'1px solid #bbf7d0' }}>
                          <div style={{ fontSize:9, fontWeight:700, color:'#16a34a', fontFamily:'JetBrains Mono,monospace', marginBottom:4, letterSpacing:1 }}>CORRECT ANSWER</div>
                          <div style={{ fontSize:13, color:'#16a34a', fontWeight:700 }}>{q.correct_answer}</div>
                        </div>
                      )}
                    </div>

                    {q.explanation&&(
                      <div style={{ marginTop:8, padding:'8px 12px', background:'#fffbeb', border:'1px solid #fde68a', borderRadius:8 }}>
                        <div style={{ fontSize:9, fontWeight:700, color:'#d97706', fontFamily:'JetBrains Mono,monospace', marginBottom:3, letterSpacing:1 }}>💡 EXPLANATION</div>
                        <div style={{ fontSize:12, color:'#78350f', lineHeight:1.65 }}>{q.explanation}</div>
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          )}

          {/* ── ANALYTICS TAB ── */}
          {tab==='analytics' && (
            <div>
              {analyzing ? (
                <div style={{ background:'#fff', border:'1px solid #e8e8f0', borderRadius:14, padding:'60px 0', textAlign:'center', boxShadow:'0 1px 3px rgba(0,0,0,.05)' }}>
                  <div style={{ width:44, height:44, borderRadius:'50%', border:'3px solid #e8e8f0', borderTop:'3px solid #7c3aed', animation:'spin .8s linear infinite', margin:'0 auto 14px' }}/>
                  <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:15, color:'#374151', marginBottom:4 }}>Analyzing your performance...</div>
                  <div style={{ fontSize:12, color:'#9ca3af' }}>Generating personalized insights for {questions.length} questions</div>
                </div>
              ) : analysisErr ? (
                <div style={{ background:'#fef2f2', border:'1px solid #fecaca', borderRadius:14, padding:28, textAlign:'center' }}>
                  <div style={{ fontSize:28, marginBottom:10 }}>⚠</div>
                  <div style={{ fontSize:14, color:'#dc2626', marginBottom:14 }}>{analysisErr}</div>
                  <button className="btn btn-primary btn-sm" onClick={generateAnalysis}>Try Again</button>
                </div>
              ) : !analysis ? (
                <div style={{ background:'#fff', border:'1px solid #e8e8f0', borderRadius:14, padding:'48px 0', textAlign:'center', boxShadow:'0 1px 3px rgba(0,0,0,.05)' }}>
                  <div style={{ fontSize:40, marginBottom:14 }}>📊</div>
                  <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:16, color:'#0f0f1a', marginBottom:8 }}>Generate Performance Analysis</div>
                  <div style={{ fontSize:13, color:'#6b7280', marginBottom:20 }}>Get detailed strengths, weaknesses, and improvement tips based on your answers.</div>
                  <button className="btn btn-primary" onClick={generateAnalysis}>📊 Analyze My Results</button>
                </div>
              ) : (
                <div style={{ display:'flex', flexDirection:'column', gap:14 }}>

                  {/* Level + Summary */}
                  <div style={{ background:'#fff', border:'1px solid #e8e8f0', borderRadius:14, padding:22, boxShadow:'0 1px 3px rgba(0,0,0,.05)' }}>
                    <div style={{ display:'flex', alignItems:'center', gap:16, marginBottom:16 }}>
                      <div style={{ textAlign:'center', background:'linear-gradient(135deg,#ede9fe,#ddd6fe)', borderRadius:12, padding:'12px 20px', flexShrink:0 }}>
                        <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:900, fontSize:20, color:'#7c3aed', marginBottom:2 }}>{analysis.level}</div>
                        <div style={{ fontSize:9, color:'#9ca3af', fontFamily:'JetBrains Mono,monospace', letterSpacing:1 }}>SKILL LEVEL</div>
                      </div>
                      <div style={{ flex:1 }}>
                        <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:14, color:'#0f0f1a', marginBottom:6 }}>Overall Assessment</div>
                        <div style={{ fontSize:13, color:'#374151', lineHeight:1.7 }}>{analysis.summary}</div>
                      </div>
                      <div style={{ textAlign:'center', background:'#f0fdf4', borderRadius:12, padding:'12px 16px', flexShrink:0 }}>
                        <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:800, fontSize:14, color:'#16a34a', marginBottom:2 }}>{analysis.readiness}</div>
                        <div style={{ fontSize:9, color:'#9ca3af', fontFamily:'JetBrains Mono,monospace', letterSpacing:1 }}>EXAM READINESS</div>
                      </div>
                    </div>

                    {/* Focus topics */}
                    {analysis.focus_topics?.length>0 && (
                      <div style={{ background:'#fef9c3', border:'1px solid #fde68a', borderRadius:9, padding:'10px 14px', display:'flex', alignItems:'center', gap:10 }}>
                        <span style={{ fontSize:16 }}>🎯</span>
                        <div>
                          <div style={{ fontSize:11, fontWeight:700, color:'#713f12', marginBottom:3 }}>Priority Study Areas</div>
                          <div style={{ fontSize:12, color:'#78350f' }}>{analysis.focus_topics.join(' → ')}</div>
                        </div>
                      </div>
                    )}
                  </div>

                  {/* Strengths + Weaknesses */}
                  <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:14 }}>
                    {/* Strengths */}
                    <div style={{ background:'#fff', border:'1px solid #e8e8f0', borderRadius:14, overflow:'hidden', boxShadow:'0 1px 3px rgba(0,0,0,.05)' }}>
                      <div style={{ padding:'12px 18px', borderBottom:'1px solid #f3f4f6', background:'#f0fdf4', display:'flex', alignItems:'center', gap:8 }}>
                        <span style={{ fontSize:16 }}>💪</span>
                        <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:14, color:'#16a34a' }}>Strengths</div>
                      </div>
                      <div style={{ padding:14 }}>
                        {(analysis.strengths||[]).length===0 ? (
                          <div style={{ fontSize:13, color:'#9ca3af', fontStyle:'italic' }}>Keep practicing to build strengths!</div>
                        ) : (analysis.strengths||[]).map((s,i) => (
                          <div key={i} style={{ display:'flex', gap:10, padding:'10px 0', borderBottom:i<(analysis.strengths||[]).length-1?'1px solid #f3f4f6':'none' }}>
                            <div style={{ width:26, height:26, borderRadius:7, background:'#dcfce7', display:'flex', alignItems:'center', justifyContent:'center', fontSize:11, fontWeight:800, color:'#16a34a', flexShrink:0 }}>✓</div>
                            <div>
                              <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:13, color:'#0f0f1a', marginBottom:3 }}>{s.topic}</div>
                              <div style={{ fontSize:12, color:'#6b7280', lineHeight:1.55 }}>{s.detail}</div>
                            </div>
                          </div>
                        ))}
                      </div>
                    </div>

                    {/* Weaknesses */}
                    <div style={{ background:'#fff', border:'1px solid #e8e8f0', borderRadius:14, overflow:'hidden', boxShadow:'0 1px 3px rgba(0,0,0,.05)' }}>
                      <div style={{ padding:'12px 18px', borderBottom:'1px solid #f3f4f6', background:'#fef2f2', display:'flex', alignItems:'center', gap:8 }}>
                        <span style={{ fontSize:16 }}>📚</span>
                        <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:14, color:'#dc2626' }}>Areas to Improve</div>
                      </div>
                      <div style={{ padding:14 }}>
                        {(analysis.weaknesses||[]).length===0 ? (
                          <div style={{ fontSize:13, color:'#9ca3af', fontStyle:'italic' }}>Great job — no major weaknesses identified!</div>
                        ) : (analysis.weaknesses||[]).map((w,i) => (
                          <div key={i} style={{ display:'flex', gap:10, padding:'10px 0', borderBottom:i<(analysis.weaknesses||[]).length-1?'1px solid #f3f4f6':'none' }}>
                            <div style={{ width:26, height:26, borderRadius:7, background:'#fee2e2', display:'flex', alignItems:'center', justifyContent:'center', fontSize:11, fontWeight:800, color:'#dc2626', flexShrink:0 }}>!</div>
                            <div>
                              <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:13, color:'#0f0f1a', marginBottom:3 }}>{w.topic}</div>
                              <div style={{ fontSize:12, color:'#6b7280', lineHeight:1.55 }}>{w.detail}</div>
                            </div>
                          </div>
                        ))}
                      </div>
                    </div>
                  </div>

                  {/* Improvement tips */}
                  <div style={{ background:'#fff', border:'1px solid #e8e8f0', borderRadius:14, overflow:'hidden', boxShadow:'0 1px 3px rgba(0,0,0,.05)' }}>
                    <div style={{ padding:'12px 18px', borderBottom:'1px solid #f3f4f6', background:'#fffbeb', display:'flex', alignItems:'center', gap:8 }}>
                      <span style={{ fontSize:16 }}>🚀</span>
                      <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:14, color:'#d97706' }}>Improvement Steps</div>
                    </div>
                    <div style={{ padding:'14px 18px' }}>
                      {(analysis.improvements||[]).map((tip,i) => (
                        <div key={i} style={{ display:'flex', gap:12, padding:'10px 0', borderBottom:i<(analysis.improvements||[]).length-1?'1px solid #f3f4f6':'none', alignItems:'flex-start' }}>
                          <div style={{ width:26, height:26, borderRadius:7, background:'linear-gradient(135deg,#fef3c7,#fde68a)', display:'flex', alignItems:'center', justifyContent:'center', fontSize:11, fontWeight:800, color:'#d97706', flexShrink:0 }}>{i+1}</div>
                          <div style={{ fontSize:13, color:'#374151', lineHeight:1.65, flex:1, paddingTop:3 }}>{tip}</div>
                        </div>
                      ))}
                    </div>
                  </div>

                  {/* Refresh button */}
                  <div style={{ textAlign:'center' }}>
                    <button className="btn btn-secondary btn-sm" onClick={generateAnalysis} style={{ fontSize:12 }}>
                      🔄 Re-analyze
                    </button>
                  </div>
                </div>
              )}
            </div>
          )}
        </>
      )}
    </div>
  );
};

export default ResultView;
